using System;
using System.Linq;
using System.Reflection;
using System.Threading.Tasks;
using LastRail.Battle;
using LastRail.Narrative;
using LastRail.Run;
using Newtonsoft.Json.Linq;
using NUnit.Framework;
namespace LastRail.Tests.EditMode {
 public sealed class StoryProgressObservationTests {
  public static readonly string[] Operations={"opn_01_last_departure","opn_02_first_signal","opn_03_water_stop"};
  public static JObject Progress(int order,long sequence){
   var raw=new JObject{["story"]=order==0?JValue.CreateNull():new JObject{["actId"]="act_01_wasteland_railway",["highestStoryProgressId"]=Operations[order-1],["highestClearedOperationId"]=Operations[order-1],["clearedOperationsJson"]=new JArray(Operations.Take(order)).ToString(),["storyFlagsJson"]="[\"flag_fixture\"]",["narrativeVersion"]="fixture-narrative-v1",["lastProgressRunId"]="run_fixture",["updatedAt"]=1720000000000L},["unlocks"]=new JArray(Operations.Skip(1).Take(order).Select(id=>new JObject{["unlockId"]="operation:"+id,["unlockedAt"]=1720000000000L}))};
   return new JObject{["kind"]="SNAPSHOT",["beforeMutationSequence"]=sequence,["mutationSequence"]=sequence,["versionSource"]=order==0?"VERIFIED_EMPTY":"STORY_PROGRESS_MUTATION",["contentHash"]=BDirectAttackInput.Digest(raw).Substring(7),["state"]=raw};
  }
  public static JObject Observation(int order=0,long sequence=0){
   var root=JObject.Parse(StoryArchiveReadModelTests.Reply(Operations.Take(Math.Min(order+1,3)).ToArray()));
   root["storyProgress"]=new JObject{["highestStoryProgressId"]=order==0?"none":Operations[order-1],["highestClearedOperationId"]=order==0?null:Operations[order-1],["order"]=order};root["clearedOperationIds"]=new JArray(Operations.Take(order));
   root["storyFlags"]=root["narrativeFlags"]=new JArray(order==0?Array.Empty<string>():new[]{"flag_fixture"});root["lastProgressRunId"]=order==0?null:"run_fixture";root["updatedAt"]=order==0?null:"2024-07-03T09:46:40.000Z";
   root["version"]="story.progress-observation.v1.20261022";var source=Progress(order,sequence);source["accountId"]="account_test";root["sourceOwner"]=source;
   root["projectionDefinition"]=new JObject{["version"]="story.progress-projection.v1.20261022",["narrativeVersion"]="fixture-narrative-v1",["coverage"]=new JArray("STORY_PROGRESS","OPERATION_UNLOCKS"),["storyProgressOrder"]=new JArray(new[]{"none"}.Concat(Operations)),["operationIds"]=new JArray(Operations),["initialOperationId"]=Operations[0],["metadata"]=root["narrative"].DeepClone()};return root;
  }
  sealed class Wire:IRunApiHttpTransport {public string Body=Observation().ToString();public int Calls;public RunApiHttpRequest Last;public Task<RunApiHttpResponse> SendAsync(RunApiHttpRequest request){Calls++;Last=request;return Task.FromResult(RunApiHttpResponse.Success(200,Body));}}
  static bool Apply(StoryArchiveReadModel model,JObject progress){var args=new object[]{progress,null};bool ok=(bool)typeof(StoryArchiveReadModel).GetMethod("TryPrepareClaim",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(model,args);if(ok)typeof(StoryArchiveReadModel).GetMethod("CommitClaim",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(model,new[]{args[1]});return ok;}
  [Test] public async Task NonemptyClaimUsesObservedDefinitionAndIndependentVersionWithoutGet(){var wire=new Wire();var session=SupportInquiryTests.Session();using var model=new StoryArchiveReadModel(wire,()=>session,()=>1);await model.RefreshAsync();Assert.That(wire.Last.Headers.Any(h=>h.Name=="X-Story-Progress-Version"),Is.True);Assert.That(model.ConfirmedProgress,Is.Not.Null);Assert.That(Apply(model,Progress(2,4)),Is.True);Assert.That(model.State.Order,Is.EqualTo(2));Assert.That(model.State.UnlockedOperations,Does.Contain(Operations[2]));Assert.That(model.ConfirmedProgress.MutationSequence,Is.EqualTo(4));Assert.That(wire.Calls,Is.EqualTo(1));Assert.That(Apply(model,Progress(1,3)),Is.True);Assert.That(model.State.Order,Is.EqualTo(2));Assert.That(Apply(model,Progress(1,4)),Is.False);await model.RefreshAsync();Assert.That(model.State.Order,Is.EqualTo(2),"Old GET cannot roll back applied progress");}
  [TestCase("hash")][TestCase("account")][TestCase("projection")][TestCase("definition")]
  public async Task InvalidObservationDoesNotBecomeReady(string fault){var root=Observation(2,4);if(fault=="hash")root["sourceOwner"]["contentHash"]="bad";if(fault=="account")root["sourceOwner"]["accountId"]="other";if(fault=="projection")root["storyProgress"]["order"]=1;if(fault=="definition")root["projectionDefinition"]["coverage"]=new JArray("ALL");var wire=new Wire{Body=root.ToString()};var session=SupportInquiryTests.Session();using var model=new StoryArchiveReadModel(wire,()=>session,()=>1);await model.RefreshAsync();Assert.That(model.Status,Is.EqualTo(StoryArchiveReadStatus.Unavailable));Assert.That(model.State,Is.Null);}
  [Test] public async Task SourceFlagsAndOtherUnlocksSurviveWithoutExposingMutableState(){var wire=new Wire();var session=SupportInquiryTests.Session();using var model=new StoryArchiveReadModel(wire,()=>session,()=>1);await model.RefreshAsync();var progress=Progress(2,4);((JArray)progress["state"]["unlocks"]).Add(new JObject{["unlockId"]="feature:fixture",["unlockedAt"]=10});progress["contentHash"]=BDirectAttackInput.Digest(progress["state"]).Substring(7);Assert.That(Apply(model,progress),Is.True);var copy=model.ConfirmedProgress.CaptureSourceState();Assert.That((string)copy["story"]["storyFlagsJson"],Does.Contain("flag_fixture"));Assert.That(copy["unlocks"].Any(x=>(string)x["unlockId"]=="feature:fixture"),Is.True);copy["story"]=null;Assert.That(model.ConfirmedProgress.CaptureSourceState()["story"].Type,Is.EqualTo(JTokenType.Object));}
  [Test] public async Task FailedObservationAndCredentialRotationDoNotLoseNewerProgressFence(){var wire=new Wire();var session=SupportInquiryTests.Session();using var model=new StoryArchiveReadModel(wire,()=>session,()=>1);await model.RefreshAsync();Assert.That(Apply(model,Progress(2,4)),Is.True);wire.Body="{}";await model.RefreshAsync();Assert.That(model.Status,Is.EqualTo(StoryArchiveReadStatus.Unavailable));session=SupportInquiryTests.Session();model.SynchronizeSession();wire.Body=Observation().ToString();await model.RefreshAsync();Assert.That(model.State.Order,Is.EqualTo(2));Assert.That(model.ConfirmedProgress.MutationSequence,Is.EqualTo(4));}
  [Test] public async Task LegacyReadDoesNotInventProgressVersion(){var wire=new Wire{Body=StoryArchiveReadModelTests.Reply(Operations[0])};var session=SupportInquiryTests.Session();using var model=new StoryArchiveReadModel(wire,()=>session,()=>1);await model.RefreshAsync();Assert.That(model.Status,Is.EqualTo(StoryArchiveReadStatus.Ready));Assert.That(Apply(model,Progress(0,0)),Is.False);Assert.That(model.ConfirmedProgress,Is.Null);}
 }
}
